Visualizing Convergence to N(0,1): Density Comparison


Code
set.seed(551)
p_true &lt;- 0.3
n_values &lt;- c(10, 30, 100, 500)
n_sim &lt;- 10000

# Simulate Wald pivot for various sample sizes
sim_wald_pivot &lt;- function(n, p, n_sim) {

  replicate(n_sim, {
    x &lt;- rbinom(1, n, p)
    p_hat &lt;- x / n
    if (p_hat &gt; 0 & p_hat &lt; 1) {
      (p_hat - p) / sqrt(p_hat * (1 - p_hat) / n)
    } else {
      NA
    }
  })
}

# Generate data for all sample sizes
pivot_data &lt;- map_dfr(n_values, ~{
  pivots &lt;- sim_wald_pivot(.x, p_true, n_sim)
  tibble(n = .x,
         n_label = paste0("n = ", .x),
         pivot = pivots[!is.na(pivots)])
})

# Overlaid density plots
pivot_data |&gt;
  mutate(n_label = factor(n_label, levels = paste0("n = ", n_values))) |&gt;
  ggplot(aes(x = pivot)) +
  geom_histogram(aes(y = after_stat(density)), bins = 60, 
                 fill = "steelblue", alpha = 0.6, color = "white") +
  stat_function(fun = dnorm, color = "red", linewidth = 1.5) +
  facet_wrap(~n_label, nrow = 1) +
  coord_cartesian(xlim = c(-4, 4)) +
  labs(x = "Wald Pivot Value",
       y = "Density",
       title = "Wald Pivot Distribution Converges to N(0,1)",
       subtitle = "Blue histogram: 10,000 simulated pivots | Red curve: N(0,1) density | True p = 0.3") +
  theme_minimal(base_size = 16)



As \(n\) increases, the histogram of simulated Wald pivots matches the red N(0,1) curve more closely.

Visualizing the Consistency Argument


Code
set.seed(551)
p_true &lt;- 0.3
n_values &lt;- c(20, 50, 100, 500)

sim_ratio &lt;- function(n, p, n_sim = 5000) {
  replicate(n_sim, {
    x &lt;- rbinom(1, n, p)
    p_hat &lt;- x/n
    if (p_hat &gt; 0 & p_hat &lt; 1) {
      sqrt(p*(1-p)) / sqrt(p_hat*(1-p_hat))
    } else {
      NA
    }
  })
}

ratio_data &lt;- map_dfr(n_values, ~{
  tibble(n = paste0("n = ", .x), 
         ratio = sim_ratio(.x, p_true))
}) |&gt; 
  filter(!is.na(ratio))

ratio_data |&gt; 
  ggplot(aes(x = ratio)) +
  geom_histogram(bins = 40, fill = "steelblue", alpha = 0.7) +
  geom_vline(xintercept = 1, color = "red", linewidth = 1.2, linetype = "dashed") +
  facet_wrap(~n, scales = "free_y") +
  labs(x = expression(sqrt(p(1-p)) / sqrt(hat(p)(1-hat(p)))),
       y = "Count",
       title = "Ratio of True SE to Estimated SE Concentrates at 1",
       subtitle = "True p = 0.3") +
  theme_minimal(base_size = 16)

