When Does the Bootstrap Test Outperform the t-Test?


Code
# Compare rejection rates under H0 (alpha control) for normal vs skewed distributions
sim_compare &lt;- function(n, dist = "normal", B_inner = 999, reps = 500) {
  replicate(reps, {
    if (dist == "normal") {
      x &lt;- rnorm(n, mean = 0)
    } else {
      x &lt;- rexp(n, rate = 1) - 1  # centered exponential (mean=0, skewed)
    }

    # t-test p-value
    p_t &lt;- t.test(x, mu = 0)$p.value

    # Bootstrap p-value
    x_sh &lt;- x - mean(x)  # shift to H0: mu = 0
    T_ob &lt;- (mean(x)) / (sd(x) / sqrt(n))
    T_bs &lt;- replicate(B_inner, {
      bs &lt;- sample(x_sh, n, replace = TRUE)
      (mean(bs)) / (sd(bs) / sqrt(n))
    })
    p_bs &lt;- mean(abs(T_bs) &gt;= abs(T_ob))

    c(p_t = p_t, p_bs = p_bs)
  }) |&gt;
    t() |&gt;
    as_tibble() |&gt;
    summarise(
      alpha_t  = mean(p_t &lt; 0.05),
      alpha_bs = mean(p_bs &lt; 0.05),
      .groups = "drop"
    ) |&gt;
    mutate(n = n, dist = dist)
}

set.seed(42)
grid &lt;- expand_grid(n = c(10, 25, 50), dist = c("normal", "skewed"))
res &lt;- map2_dfr(grid$n, grid$dist, sim_compare)

res |&gt;
  pivot_longer(starts_with("alpha"), names_to = "method", values_to = "type1") |&gt;
  mutate(
    method = recode(method, alpha_t = "t-test", alpha_bs = "Bootstrap test"),
    dist   = recode(dist, normal = "Normal population", skewed = "Skewed population (Exp-1)")
  ) |&gt;
  ggplot(aes(x = factor(n), y = type1, fill = method)) +
  geom_col(position = "dodge", alpha = 0.85) +
  geom_hline(yintercept = 0.05, linetype = "dashed", color = "black", linewidth = 1) +
  facet_wrap(~dist) +
  scale_fill_manual(values = c("t-test" = "steelblue", "Bootstrap test" = "#27ae60")) +
  scale_y_continuous(labels = scales::percent, limits = c(0, 0.12)) +
  labs(
    title = expression("Type I Error Rate Under " * H[0] * " at " * alpha * " = 0.05"),
    subtitle = "Both methods well-calibrated for normal; bootstrap slightly better for small skewed samples",
    x = "Sample size (n)", y = "Empirical Type I error rate",
    fill = NULL
  ) +
  theme(legend.position = "bottom")

Simulation Study: Comparison of Methods


Code
# Under H0: compare Type I error
# Under Ha: compare power

run_three_tests &lt;- function(n1 = 20, n2 = 20, delta = 0,
                            dist = "normal", B_inner = 499) {
  if (dist == "normal") {
    x1 &lt;- rnorm(n1, mean = delta); x2 &lt;- rnorm(n2, mean = 0)
  } else {
    x1 &lt;- rexp(n1, 1) - 1 + delta; x2 &lt;- rexp(n2, 1) - 1
  }

  # Parametric t-test
  p_t &lt;- t.test(x1, x2)$p.value

  # Bootstrap (pooled centered)
  grand &lt;- mean(c(x1, x2))
  x1c   &lt;- x1 - mean(x1) + grand
  x2c   &lt;- x2 - mean(x2) + grand
  pool  &lt;- c(x1c, x2c)
  T_ob  &lt;- mean(x1) - mean(x2)
  T_bs  &lt;- replicate(B_inner, {
    mean(sample(pool, n1, T)) - mean(sample(pool, n2, T))
  })
  p_b &lt;- mean(abs(T_bs) &gt;= abs(T_ob))

  # Permutation
  comb  &lt;- c(x1, x2)
  T_pm  &lt;- replicate(B_inner, {
    pm &lt;- sample(comb)
    mean(pm[1:n1]) - mean(pm[(n1+1):(n1+n2)])
  })
  p_p &lt;- (sum(abs(T_pm) &gt;= abs(T_ob)) + 1) / (B_inner + 1)

  c(p_t = p_t, p_boot = p_b, p_perm = p_p)
}

set.seed(99)
scenarios_cmp &lt;- expand_grid(delta = c(0, 1), dist = c("normal", "skewed"))

res_cmp &lt;- scenarios_cmp |&gt;
  rowwise() |&gt;
  mutate(
    sims = list(replicate(300, run_three_tests(delta = delta, dist = dist,
                                               B_inner = 299)) |&gt;
                  t() |&gt; as_tibble())
  ) |&gt;
  unnest(sims) |&gt;
  pivot_longer(starts_with("p_"), names_to = "method", values_to = "pval") |&gt;
  group_by(delta, dist, method) |&gt;
  summarise(rejection = mean(pval &lt; 0.05), .groups = "drop") |&gt;
  mutate(
    method = recode(method, p_t = "t-test", p_boot = "Bootstrap", p_perm = "Permutation"),
    scenario = paste0(ifelse(dist == "normal", "Normal", "Skewed"),
                      ", \u03b4 = ", delta),
    quantity = ifelse(delta == 0, "Type I error (H\u2080 true)", "Power (H\u2090 true)")
  )

ggplot(res_cmp, aes(x = method, y = rejection, fill = method)) +
  geom_col(alpha = 0.85) +
  geom_hline(yintercept = 0.05, linetype = "dashed") +
  facet_wrap(~scenario, nrow = 2) +
  scale_fill_manual(values = c("t-test" = "steelblue", 
                               "Bootstrap" = "#e74c3c", 
                               "Permutation" = "#27ae60")) +
  scale_y_continuous(labels = scales::percent, limits = c(0, 1)) +
  labs(
    title = "Comparison of Tests: Type I Error (delta=0) and Power (delta=1)",
    subtitle = "n1 = n2 = 20. All tests well-calibrated; permutation slightly conservative for skewed data.",
    x = "Method", y = "Rejection rate", fill = NULL
  ) +
  theme(legend.position = "bottom", strip.text = element_text(size = 14))

