set.seed(551)

sim_ci_width &lt;- function(rho, n = 25, sigma = 10, B = 2000) {
  map_dfr(seq_len(B), function(i) {
    L  &lt;- chol(sigma^2 * matrix(c(1, rho, rho, 1), 2))
