set.seed(551)
B_sim &lt;- 1000

compare_methods &lt;- function(n1 = 25, n2 = 25,
                             shape = 1.5, rate1 = 0.25, rate2 = 0.25) {
  replicate(B_sim, {
    x1  &lt;- rgamma(n1, shape = shape, rate = rate1)
    x2  &lt;- rgamma(n2, shape = shape, rate = rate2)
    Ns  &lt;- n1 + n2
    all &lt;- c(x1, x2)

    p_t    &lt;- t.test(x1, x2)$p.value
    p_perm &lt;- {
      t0    &lt;- mean(x1) - mean(x2)
      perms &lt;- replicate(499, {
        idx &lt;- sample(Ns)
        mean(all[idx[seq_len(n1)]]) - mean(all[idx[(n1+1):Ns]])
      })
      mean(abs(perms) &gt;= abs(t0))
    }
    p_wilcox &lt;- wilcox.test(x1, x2)$p.value
    c(Welch = p_t, Permutation = p_perm, Wilcoxon = p_wilcox)
  }) |&gt; t() |&gt; as_tibble()
}

null_res &lt;- compare_methods(rate1 = 0.25, rate2 = 0.25)
alt_res  &lt;- compare_methods(rate1 = 0.25, rate2 = 0.35)

bind_rows(
